 static T[] All<T>(Scene s)where T:Component{return s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<T>(true)).ToArray();}
 static Material Mat(string n,Color c){var m=AssetDatabase.LoadAssetAtPath<Material>(F+n+".mat");if(!m){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,F+n+".mat");}m.color=c;m.SetFloat("_Glossiness",n.Contains("ceramic")?.34f:.12f);return m;}
