 static void Pipe(Transform p,Vector3 a,Vector3 b,float r){var t=Box(p,"Exposed pipe",(a+b)*.5f,new Vector3(r*2,(a-b).magnitude*.5f,r*2),steel,PrimitiveType.Cylinder);t.rotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static Mesh Save(Mesh mesh,string name){string path=F+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
