 static void Bowl(Transform p,Vector3 at,Vector3 scale,bool seat){
  float[] radii=seat?new[]{.79f,1f,1f,.76f,.76f,.79f}:new[]{.05f,.68f,1f,1f,.87f,.58f,.05f};
  float[] ys=seat?new[]{0f,0f,.07f,.07f,0f,0f}:new[]{-.23f,-.18f,-.04f,.03f,.03f,-.14f,-.16f};int n=40;var v=new List<Vector3>();var tri=new List<int>();
  for(int j=0;j<radii.Length;j++)for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;v.Add(new Vector3(Mathf.Cos(a)*radii[j]*.5f,ys[j],Mathf.Sin(a)*radii[j]*.5f));}
  for(int j=0;j<radii.Length-1;j++)for(int i=0;i<n;i++){int k=j*(n+1)+i;tri.AddRange(new[]{k,k+n+1,k+1,k+1,k+n+1,k+n+2});}
  var mesh=new Mesh();mesh.SetVertices(v);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateBounds();var t=G(p,seat?"Thick oval toilet seat":"Hollow ceramic basin",at);t.localScale=scale;t.gameObject.AddComponent<MeshFilter>().sharedMesh=Save(mesh,seat?"Toilet seat ring":"Recessed ceramic bowl");t.gameObject.AddComponent<MeshRenderer>().sharedMaterial=seat?dark:ceramic;
 }
 static Mesh Rag(int id,bool strip){var rng=new System.Random(id*153+17);float a=(float)rng.NextDouble()*5,b=(float)rng.NextDouble()*5;int n=strip?18:12,m=strip?4:12;var v=new List<Vector3>();var uv=new List<Vector2>();var clean=new List<int>();var stained=new List<int>();
  for(int j=0;j<=m;j++)for(int i=0;i<=n;i++){float u=i/(float)n,w=j/(float)m;float edge=Mathf.Sin(w*17+a)*.035f;float x=(u-.5f)*(1+edge)+Mathf.Sin(w*8+b)*.045f;float z=(w-.5f)*(1+Mathf.Sin(u*12+b)*.06f);float h=strip?.035f+.025f*Mathf.Sin(u*7+a)+.012f*Mathf.Cos(w*5+u*9):.025f+.13f*Mathf.Sin(u*Mathf.PI)*Mathf.Sin(w*Mathf.PI)+.023f*Mathf.Sin(u*11+w*8+a)+.012f*Mathf.Cos(w*14+b);v.Add(new Vector3(x,h,z));uv.Add(new Vector2(u,w));}
  for(int j=0;j<m;j++)for(int i=0;i<n;i++){int k=j*(n+1)+i;float u=i/(float)n,w=j/(float)m;bool red=Mathf.Pow((u-.40f)*1.8f,2)+Mathf.Pow((w-.57f)*1.8f,2)<.11f+.045f*Mathf.Sin(i*2+j*3+a);var dst=red?stained:clean;int[] t={k,k+n+1,k+1,k+1,k+n+1,k+n+2};dst.AddRange(t); // Duplicate reverse faces with separate vertices to preserve normals.
  }
  int top=v.Count;var vv=v.ToArray();v.AddRange(vv);uv.AddRange(uv.ToArray());foreach(var list in new[]{clean,stained}){var ts=list.ToArray();for(int k=0;k<ts.Length;k+=3)list.AddRange(new[]{ts[k]+top,ts[k+2]+top,ts[k+1]+top});}
  var mesh=new Mesh();mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.subMeshCount=2;mesh.SetTriangles(clean,0);mesh.SetTriangles(stained,1);mesh.RecalculateNormals();mesh.RecalculateBounds();return Save(mesh,"Irregular "+(strip?"bandage ":"cloth ")+id);
 }
 static void Cloth(Transform parent,Vector3 at,Vector3 size,int id,bool strip=false){var t=G(parent,strip?"Twisted loose bloodied bandage":"Crumpled stained work fabric",at);t.localScale=size;var rng=new System.Random(id*13);t.rotation=Quaternion.Euler(0,(float)rng.NextDouble()*360,0);t.gameObject.AddComponent<MeshFilter>().sharedMesh=Rag(id%9,strip);t.gameObject.AddComponent<MeshRenderer>().sharedMaterials=new[]{id%3==0?orange:linen,blood};}
 public static void Apply(){if(EditorApplication.isPlaying)throw new Exception("Stop Play first");ceramic=Mat("Worn ivory ceramic",new Color(.48f,.49f,.41f));steel=Mat("Washroom old iron fittings",new Color(.17f,.20f,.18f));dark=Mat("Black bakelite toilet seats",new Color(.045f,.051f,.042f));partition=Mat("Faded washroom cubicle paint",new Color(.23f,.29f,.25f));tile=AssetDatabase.LoadAssetAtPath<Material>(F+"Stained bathhouse tile.mat");linen=AssetDatabase.LoadAssetAtPath<Material>(F+"Dusty bedding and bandage linen.mat");blood=AssetDatabase.LoadAssetAtPath<Material>(F+"Old dried blood on fabric.mat");orange=AssetDatabase.LoadAssetAtPath<Material>(F+"Faded worker overalls.mat");
 var orig=SceneManager.GetActiveScene();var s=SceneManager.GetSceneByPath("Assets/Scenes/3D/FactoryRooms/FactoryWashroomF2.unity");bool opened=!s.isLoaded;if(opened)s=EditorSceneManager.OpenScene("Assets/Scenes/3D/FactoryRooms/FactoryWashroomF2.unity",OpenSceneMode.Additive);try{
