 foreach(var v in All<Recoil3DSpriteVisual>(s))if(new[]{"Dado","Tile grout","Dirty mirror","Sink basin","Drain pipe","Tap","Cubicle partition","Cubicle door","Door latch"}.Contains(v.name)){v.suppressed=true;v.Sync();EditorUtility.SetDirty(v);}
