 for(int i=0;i<3;i++)Box(g,"Full depth cubicle partition",new Vector3(6.35f+i*1.22f,1.24f,3.72f),new Vector3(.10f,2.25f,1.9f),partition);
 for(int i=0;i<2;i++){float x=6.96f+i*1.22f;var p=G(g,"Toilet cubicle "+i,new Vector3(x,0,3.8f));Box(p,"Ceramic cistern",new Vector3(x,.93f,4.4f),new Vector3(.48f,.54f,.23f),ceramic);Box(p,"Cistern lid",new Vector3(x,1.22f,4.4f),new Vector3(.52f,.055f,.27f),ceramic);Box(p,"Flush handle",new Vector3(x+.17f,1.04f,4.27f),new Vector3(.10f,.04f,.04f),steel);Box(p,"Toilet pedestal",new Vector3(x,.22f,3.96f),new Vector3(.31f,.44f,.40f),ceramic,PrimitiveType.Capsule);Bowl(p,new Vector3(x,.50f,3.86f),new Vector3(.49f,.8f,.68f),false);Bowl(p,new Vector3(x,.55f,3.86f),new Vector3(.51f,1,.69f),true);
 var hinge=G(p,"Partly open cubicle door",new Vector3(x-.50f,0,2.79f));Box(hinge,"Thick wooden door",new Vector3(x-.04f,1.20f,2.79f),new Vector3(.90f,2.10f,.075f),partition);Box(hinge,"Latch",new Vector3(x+.26f,1.14f,2.735f),new Vector3(.12f,.09f,.04f),steel);hinge.rotation=Quaternion.identity;var use=G(p,"Cubicle door interaction",new Vector3(x,.85f,2.79f)).gameObject.AddComponent<RecoilCubicleDoor>();use.hinge=hinge;use.interactionDuration=0;use.interactionRange=.60f;use.itemId="washroom_cubicle_"+i;use.ResetItem();}
 var aftermath=world.transform.Find("1978 conflict aftermath - editable");if(aftermath){bool moveRail=aftermath.GetComponentsInChildren<Transform>().Any(t=>t.name=="Overhead changing rail"&&t.position.x>3);foreach(var h in aftermath.GetComponentsInChildren<Transform>().Where(t=>t.name=="Overhead changing rail"||t.name=="Rusty hanging chain"||t.name=="Clothes hook"||t.name=="Work shirt on hanging hook"))if(moveRail)h.position+=Vector3.left*2.6f;foreach(var t in aftermath.GetComponentsInChildren<Transform>().Where(t=>t.name=="Crumpled linen"||t.name=="Dried blood absorbed in linen"||t.name=="Laundry tub waiting to be cleaned").ToArray())if(t)Object.DestroyImmediate(t.gameObject);}
 for(int i=0;i<3;i++){float x=new[]{2.9f,4.65f,6.25f}[i],z=new[]{1.75f,2.5f,1.9f}[i];var tub=G(g,"Overflowing laundry trough "+i,new Vector3(x,0,z));Box(tub,"Trough bottom",new Vector3(x,.12f,z),new Vector3(.82f,.10f,.65f),steel);foreach(float side in new[]{-1f,1f}){Box(tub,"Trough side",new Vector3(x+side*.39f,.27f,z),new Vector3(.045f,.27f,.65f),steel);Box(tub,"Trough end",new Vector3(x,.27f,z+side*.30f),new Vector3(.82f,.27f,.045f),steel);}var rng=new System.Random(35+i);for(int j=0;j<10;j++){float dx=(float)rng.NextDouble()*.55f-.275f,dz=(float)rng.NextDouble()*.4f-.2f;Cloth(tub,new Vector3(x+dx,.24f+j*.018f,z+dz),new Vector3(.35f+(float)rng.NextDouble()*.25f,.7f+(float)rng.NextDouble(),.3f+(float)rng.NextDouble()*.23f),i*11+j,j%4==0);}}
 for(int i=0;i<5;i++)Cloth(g,new Vector3(2.65f+i*.83f,.025f,1.65f+(i%3)*.27f),new Vector3(i%2==0?.65f:.36f,.8f,.19f+i%2*.25f),40+i,true);
 if(g.GetComponentsInChildren<Collider>().Length+g.GetComponentsInChildren<Collider2D>().Length!=0||All<Collider2D>(s).Length!=collision)throw new Exception("Collision changed");if(!routes.SequenceEqual(All<RecoilDoor>(s).Select(d=>d.transform.position+"|"+d.destinationScene+"|"+d.destinationSpawn)))throw new Exception("Route changed");foreach(var r in g.GetComponentsInChildren<Renderer>())if(r.bounds.min.z<1f)throw new Exception("Prop enters player lane: "+r.name);
